Analisando o problema: as trocas de linhas não afetam a estrutura de colunas e vice-versa (trocar colunas age uniformemente em todas as linhas). Logo, basta manter uma permutação de linhas R e uma permutação de colunas C, e o aluno final na célula (i, j) é o que começou em (R[i], C[j]), ou seja, `(R[i]-1)*M + C[j]`. Isso é O(N + M + P + N·M), sem armazenar a matriz N×M completa. Para a saída (até ~8 MB), uso um Buffer pré-alocado com conversão manual de dígitos e leitura de entrada byte a byte.

```javascript
const fs = require('fs');

function main() {
  let data;
  try {
    data = fs.readFileSync(0);
  } catch (e) {
    data = fs.readFileSync('/dev/stdin');
  }
  const len = data.length;
  let pos = 0;

  function nextInt() {
    while (pos < len && data[pos] <= 32) pos++;
    let n = 0;
    while (pos < len) {
      const c = data[pos];
      if (c < 48 || c > 57) break;
      n = n * 10 + (c - 48);
      pos++;
    }
    return n;
  }

  const N = nextInt();
  const M = nextInt();
  const P = nextInt();

  // R[i] = linha original cujos alunos estão agora na linha i
  // C[j] = coluna original cujas células estão agora na coluna j
  const R = new Int32Array(N + 1);
  const C = new Int32Array(M + 1);
  for (let i = 1; i <= N; i++) R[i] = i;
  for (let j = 1; j <= M; j++) C[j] = j;

  for (let p = 0; p < P; p++) {
    while (pos < len && data[pos] <= 32) pos++;
    const op = data[pos++]; // 76 = 'L', 67 = 'C'
    const a = nextInt();
    const b = nextInt();
    if (op === 76) {
      const t = R[a]; R[a] = R[b]; R[b] = t;
    } else {
      const t = C[a]; C[a] = C[b]; C[b] = t;
    }
  }

  // Buffer de saída: no máx 7 dígitos + 1 separador por número
  const out = Buffer.allocUnsafe(8 * N * M + 16);
  let o = 0;

  for (let i = 1; i <= N; i++) {
    const base = (R[i] - 1) * M;
    for (let j = 1; j <= M; j++) {
      let v = base + C[j];
      const start = o;
      do {
        out[o++] = 48 + (v % 10);
        v = (v / 10) | 0;
      } while (v > 0);
      for (let x = start, y = o - 1; x < y; x++, y--) {
        const t = out[x]; out[x] = out[y]; out[y] = t;
      }
      out[o++] = 32; // espaço
    }
    o--; // substitui o último espaço por quebra de linha
    out[o++] = 10;
  }

  let written = 0;
  while (written < o) {
    written += fs.writeSync(1, out, written, o - written);
  }
}

main();
```

